insert into public.games (id, title, year, platforms, version, series, main, extra, "full", synopsis, note, igdb_query, source) values
  ('persona-revelations-persona', 'Revelations: Persona', 1996, 'PSP / PS Vita', 'Shin Megami Tensei: Persona (PSP, 2009)', 'persona', 38, 52, 80, 'Un grupo de estudiantes de St. Hermelin juega a un ritual llamado «Persona» y despierta el poder de invocar sus alter egos. Poco después la ciudad de Mikage queda atrapada en una realidad distorsionada por una corporación y un experimento fallido.', 'El port de PSP restaura el contenido que se recortó en Occidente (incluido el escenario de la Reina de las Nieves) y mejora la interfaz.', null, 'catalog'),
  ('persona-persona-2-innocent-sin', 'Persona 2: Innocent Sin', 1999, 'PSP / PS Vita', 'Remake de PSP (2011)', 'persona', 40, 50, 72, 'En Sumaru los rumores se hacen realidad. Tatsuya Suou y sus compañeros se enfrentan al Joker, una figura que cumple deseos a cambio de robar los sueños de la gente, mientras desentierran un pasado que habían olvidado.', 'La versión de PSP añade eventos nuevos y está traducida oficialmente, a diferencia del original de PS1 que nunca salió de Japón.', null, 'catalog'),
  ('persona-persona-2-eternal-punishment', 'Persona 2: Eternal Punishment', 2000, 'PS1 / PS3 / PSP', 'Versión de PS1 (PS Store)', 'persona', 38, 48, 62, 'Secuela directa de Innocent Sin vista desde los ojos de la periodista Maya Amano. El mundo ha cambiado, pero los rumores vuelven a deformar la realidad y alguien recuerda lo que nadie debería recordar.', 'El remake de PSP solo salió en Japón, así que la mejor opción jugable en inglés es la de PS1.', null, 'catalog'),
  ('persona-persona-3-reload', 'Persona 3 Reload', 2024, 'PS5 / Xbox / PC / Switch 2', 'Reload + DLC Episode Aigis', 'persona', 60, 78, 110, 'Cada noche existe una hora oculta, la Dark Hour, en la que los humanos se convierten en ataúdes y las Sombras cazan. Un estudiante recién llegado se une al SEES para escalar la torre Tartarus y descubrir qué la conecta con el fin de todo.', 'Remake completo con calidad moderna. Añade Episode Aigis (The Answer), el epílogo canónico de unas 30 h.', null, 'catalog'),
  ('persona-persona-4-golden', 'Persona 4 Golden', 2008, 'PC / PS4 / Xbox / Switch', 'Golden (2012)', 'persona', 56, 78, 112, 'Un año en el pueblo rural de Inaba. Aparecen cadáveres colgados de antenas y circula el rumor del Midnight Channel. El protagonista y sus amigos entran en la televisión para resolver los asesinatos antes de que caiga la niebla.', 'Golden añade un personaje, eventos sociales, un epílogo extendido y un mes extra de calendario.', null, 'catalog'),
  ('persona-persona-5-royal', 'Persona 5 Royal', 2016, 'PC / PS4 / PS5 / Xbox / Switch', 'Royal (2019)', 'persona', 102, 122, 150, 'Tokio de día, ladrones de corazones de noche. Joker y los Phantom Thieves entran en los Palacios cognitivos de adultos corruptos para robarles su deseo distorsionado y obligarles a confesar.', 'Royal añade un semestre nuevo, nuevos confidentes, un palacio extra y un final adicional. La versión definitiva.', null, 'catalog'),
  ('persona-persona-5-strikers', 'Persona 5 Strikers', 2020, 'PC / PS4 / Switch', 'Edición estándar', 'persona', 35, 46, 72, 'Secuela canónica de P5 situada el verano siguiente. Los Phantom Thieves viajan por Japón para investigar unas Jails que están cambiando a la gente, ahora con combate de acción en tiempo real.', 'Jugar después de Persona 5 Royal (las referencias son al final original, sin spoilers de Royal).', null, 'catalog'),
  ('fe-fire-emblem-shadow-dragon', 'Fire Emblem: Shadow Dragon', 2008, 'DS', 'Remake DS de Shadow Dragon and the Blade of Light', 'fe', 20, 25, 35, 'Marth, príncipe exiliado de Altea, reúne un ejército para derrotar al Dragón Oscuro Medeus. El primer Fire Emblem, contado de nuevo.', 'Sustituye al original de Famicom (1990).', null, 'catalog'),
  ('fe-fire-emblem-echoes-shadows-of-valentia', 'Fire Emblem Echoes: Shadows of Valentia', 2017, '3DS', 'Remake 3DS de Gaiden', 'fe', 35, 45, 62, 'En Valentia, Alm se alza contra el Imperio de Rigel mientras su amiga de la infancia Celica busca respuestas sobre los dioses. Dos ejércitos, dos caminos.', 'Sustituye a Fire Emblem Gaiden (1992). Totalmente doblado y con mazmorras exploradas.', null, 'catalog'),
  ('fe-new-mystery-of-the-emblem', 'New Mystery of the Emblem', 2010, 'DS', 'Remake DS (traducción de fans)', 'fe', 32, 42, 58, 'Segunda guerra de Marth. Archanea vuelve a hundirse en el caos y aparece un avatar creado por el jugador como estratega. Cierra el arco de Marth.', 'Solo salió en Japón. El Libro 1 de Mystery of the Emblem ya está cubierto por Shadow Dragon.', null, 'catalog'),
  ('fe-genealogy-of-the-holy-war', 'Genealogy of the Holy War', 1996, 'SNES', 'Super Famicom (traducción de fans)', 'fe', 40, 50, 70, 'Una tragedia en dos generaciones. Sigurd lucha por el reino de Jugdral y, años después, su hijo Seliph debe acabar lo que él empezó. Mapas enormes y herencia entre personajes.', 'Solo en Japón. Hay remake anunciado como rumor desde hace años, pero ninguno oficial.', null, 'catalog'),
  ('fe-thracia-776', 'Thracia 776', 1999, 'SNES', 'Super Famicom (traducción de fans)', 'fe', 35, 45, 65, 'Leif, príncipe de Leonster, lidera una resistencia mal armada en la península de Thracia. Ocurre durante el salto temporal de Genealogy. Es el más difícil de la saga.', 'Solo en Japón. Jugar después de la primera generación de Genealogy (o del juego entero).', null, 'catalog'),
  ('fe-the-binding-blade', 'The Binding Blade', 2002, 'GBA', 'GBA (traducción de fans)', 'fe', 25, 30, 45, 'Roy, hijo del marqués de Pherae, toma el mando cuando el rey de Bern declara la guerra al continente de Elibe con ayuda de dragones.', 'Solo en Japón. Cronológicamente va después de Blazing Blade, pero salió antes.', null, 'catalog'),
  ('fe-the-blazing-blade', 'The Blazing Blade', 2003, 'GBA (Switch Online)', 'GBA (Fire Emblem en Occidente)', 'fe', 25, 35, 50, 'Lyn, Eliwood y Hector viajan por Elibe para detener a Nergal, un hechicero que quiere abrir la puerta del mundo de los dragones. Precuela de Binding Blade.', 'El primero que llegó a Occidente. En Nintendo Switch Online.', null, 'catalog'),
  ('fe-the-sacred-stones', 'The Sacred Stones', 2004, 'GBA (Switch Online)', 'GBA', 'fe', 20, 27, 40, 'Los gemelos Eirika y Ephraim de Renais luchan contra el imperio de Grado, que ha empezado a destruir las piedras sagradas que contenían al Rey Demonio.', 'Buen punto de entrada: corto y con mapa mundial para entrenar.', null, 'catalog'),
  ('fe-path-of-radiance', 'Path of Radiance', 2005, 'GameCube', 'GameCube', 'fe', 30, 40, 55, 'Ike, un joven mercenario, protege a la princesa Elincia cuando Daein invade Crimea. Primer Fire Emblem en 3D, con temas de racismo entre beorc y laguz.', 'Es caro de conseguir físicamente; aun así es la única versión.', null, 'catalog'),
  ('fe-radiant-dawn', 'Radiant Dawn', 2007, 'Wii / Wii U', 'Wii', 'fe', 45, 58, 80, 'Tres años después de Path of Radiance. Desde los ojos de Micaiah en Daein ocupado hasta una guerra que despierta a la diosa. Secuela directa.', 'Difícil incluso en Normal. Juega Path of Radiance antes.', null, 'catalog'),
  ('fe-fire-emblem-awakening', 'Fire Emblem Awakening', 2012, '3DS', '3DS', 'fe', 30, 45, 75, 'Chrom, príncipe de Ylisse, rescata a un estratega amnésico (tú). Juntos se enfrentan a un futuro apocalíptico y a viajeros del tiempo. El juego que salvó la saga.', 'Descendiente lejana de la historia de Marth.', null, 'catalog'),
  ('fe-fire-emblem-fates', 'Fire Emblem Fates', 2015, '3DS', 'Las 3 rutas (Birthright, Conquest, Revelation)', 'fe', 90, 125, 190, 'Corrin, criado por la familia real de Nohr, descubre que nació en Hoshido. Debe elegir bando o rebelarse contra ambos. Cada ruta es un juego completo.', 'Las horas suman las tres rutas. Si solo juegas una, divide aproximadamente entre tres (Conquest es la mejor en jugabilidad).', null, 'catalog'),
  ('fe-fire-emblem-three-houses', 'Fire Emblem: Three Houses', 2019, 'Switch / Switch 2', 'Con DLC Cindered Shadows', 'fe', 50, 85, 220, 'Eres profesor en el Monasterio de Garreg Mach y eliges una de tres casas. Cinco años después, tus alumnos se convertirán en líderes de una guerra entre ellos.', 'Una ruta ≈ 50 h. Las cuatro rutas completas ≈ 200 h. Es lo que más horas puede comerse de la biblioteca.', null, 'catalog'),
  ('fe-fire-emblem-engage', 'Fire Emblem Engage', 2023, 'Switch / Switch 2', 'Con Fell Xenologue', 'fe', 40, 55, 85, 'Alear, el Dragón Divino, despierta tras mil años y reúne los Anillos del Emblema, que invocan a héroes de toda la saga para frenar el regreso del Dragón Caído.', 'El mejor combate táctico de la era moderna.', null, 'catalog'),
  ('ff-final-fantasy', 'Final Fantasy', 1987, 'PC / PS4 / Switch / Xbox / móvil', 'Pixel Remaster', 'ff', 13, 16, 21, 'Cuatro Guerreros de la Luz llegan con cristales apagados en un mundo en decadencia. Su misión: devolver la luz a los elementos y romper un bucle temporal de dos mil años.', 'El Pixel Remaster respeta el diseño original con banda sonora orquestada y mejoras de calidad de vida.', null, 'catalog'),
  ('ff-final-fantasy-ii', 'Final Fantasy II', 1988, 'PC / PS4 / Switch / Xbox / móvil', 'Pixel Remaster', 'ff', 15, 20, 27, 'El Imperio de Palamecia arrasa los reinos con ayuda de demonios. Cuatro huérfanos se unen a la rebelión en el primer FF con una historia dramática y personajes con nombre propio.', 'Tiene el sistema de progresión por uso, que puede sentirse raro. El Pixel Remaster lo suaviza.', null, 'catalog'),
  ('ff-final-fantasy-iii', 'Final Fantasy III', 1990, 'PC / PS4 / Switch / Xbox / móvil', 'Pixel Remaster', 'ff', 18, 22, 30, 'Un terremoto revela una cueva con un cristal que elige a cuatro jóvenes de Ur. Introduce el sistema de trabajos (jobs) que definirá a la saga.', 'Existe también un remake 3D de DS con personajes reescritos; el Pixel Remaster es el más fiel.', null, 'catalog'),
  ('ff-final-fantasy-iv', 'Final Fantasy IV', 1991, 'PC / PS4 / Switch / Xbox / móvil', 'Pixel Remaster', 'ff', 22, 27, 35, 'Cecil, capitán de los Alas Rojas de Baron, recibe órdenes de robar cristales a pueblos inocentes. Su caída en desgracia y redención es el primer gran melodrama de la saga.', 'Si te quedas con ganas: The After Years (secuela) está en The Complete Collection de PSP.', null, 'catalog'),
  ('ff-final-fantasy-v', 'Final Fantasy V', 1992, 'PC / PS4 / Switch / Xbox / móvil', 'Pixel Remaster', 'ff', 31, 39, 55, 'Bartz, un viajero errante, se cruza con una princesa, un pirata y un anciano sin memoria. El viento se ha detenido y los cristales se rompen uno a uno ante el resurgir de Exdeath.', 'El sistema de trabajos más profundo de la saga.', null, 'catalog'),
  ('ff-final-fantasy-vi', 'Final Fantasy VI', 1994, 'PC / PS4 / Switch / Xbox / móvil', 'Pixel Remaster', 'ff', 35, 45, 62, 'La magia desapareció hace mil años y el Imperio Gestahliano quiere recuperarla. Terra, una joven con poderes, es el centro de un reparto coral enfrentado al bufón Kefka.', 'Uno de los mejores de la saga. El Pixel Remaster tiene la mejor banda sonora y traducción.', null, 'catalog'),
  ('ff-final-fantasy-vii', 'Final Fantasy VII', 1997, 'PC / PS4 / Switch / Xbox / móvil', 'Original (PC / consolas, 2019)', 'ff', 37, 47, 82, 'Cloud, un exSOLDADO mercenario, se une a AVALANCHE contra la corporación Shinra, que drena la energía del planeta. Pronto la persecución de Sefirot le obliga a enfrentarse a su propio pasado.', 'El original es la historia completa. La trilogía Remake/Rebirth es una reinterpretación con cambios de guion y su tercera parte aún no ha salido; mejor jugarla después.', null, 'catalog'),
  ('ff-final-fantasy-viii', 'Final Fantasy VIII', 1999, 'PC / PS4 / Switch / Xbox', 'Remastered', 'ff', 40, 52, 82, 'Squall Leonhart, estudiante del Jardín de Balamb, se forma como mercenario de SeeD. Una misión contra la hechicera Edea lo arrastra a una historia de amor y tiempo comprimido.', 'Remastered permite acelerar el juego x3 y desactivar encuentros: muy útil para el famoso sistema de Enlaces.', null, 'catalog'),
  ('ff-final-fantasy-ix', 'Final Fantasy IX', 2000, 'PC / PS4 / Switch / Xbox / móvil', 'Port 2016', 'ff', 40, 52, 82, 'Yitán, ladrón de una compañía de teatro, secuestra a la princesa Garnet de Alexandria, que en realidad quería huir. Un homenaje a la fantasía clásica de la saga.', 'El port incluye potenciadores opcionales (velocidad x3, sin encuentros) para quien vaya con prisa.', null, 'catalog'),
  ('ff-final-fantasy-x', 'Final Fantasy X', 2001, 'PC / PS4 / Switch / Xbox', 'HD Remaster (versión International)', 'ff', 50, 72, 120, 'Tidus, estrella del blitzbol, es arrastrado mil años al futuro, al mundo de Spira. Allí escolta a la invocadora Yuna en su peregrinaje para derrotar a Sinh, el monstruo que asola el mundo.', 'El HD Remaster usa la versión International, con el tablero de esferas experto y jefes extra.', null, 'catalog'),
  ('ff-final-fantasy-x-2', 'Final Fantasy X-2', 2003, 'PC / PS4 / Switch / Xbox', 'HD Remaster (con Last Mission)', 'ff', 25, 38, 60, 'Dos años después del Calma Eterna, Yuna se convierte en cazadora de esferas al ver una grabación de alguien que se parece a Tidus. Tono más ligero y combate de cambios de vestidor.', 'Secuela directa de X. Viene incluido en la misma colección.', null, 'catalog'),
  ('ff-final-fantasy-xii', 'Final Fantasy XII', 2006, 'PC / PS4 / Switch / Xbox', 'The Zodiac Age', 'ff', 50, 72, 110, 'Ivalice está dividida entre los imperios de Archadia y Rozarria. Vaan, un huérfano callejero, se cruza con la princesa Ashe, que busca recuperar su reino. Política, piratas del aire y gambits.', 'The Zodiac Age añade el sistema de trabajos dobles y acelerador x4. La versión a jugar.', null, 'catalog'),
  ('ff-final-fantasy-xiii', 'Final Fantasy XIII', 2009, 'PC / Xbox / PS3', 'PC / Xbox (retrocompatible)', 'ff', 47, 60, 80, 'Lightning y un grupo de desconocidos son marcados como l''Cie por un fal''Cie, entidades divinas que les dan una misión sin explicarla. Huyen del mundo flotante de Cocoon.', 'Empieza muy lineal; se abre de verdad a mitad de juego.', null, 'catalog'),
  ('ff-final-fantasy-xiii-2', 'Final Fantasy XIII-2', 2011, 'PC / Xbox / PS3', 'PC / Xbox (retrocompatible)', 'ff', 28, 42, 78, 'Serah busca a su hermana Lightning, desaparecida del tiempo, junto a Noel, un viajero de un futuro sin esperanza. Viajes temporales y paradojas.', 'Secuela directa de XIII.', null, 'catalog'),
  ('ff-lightning-returns-ff-xiii', 'Lightning Returns: FF XIII', 2013, 'PC / Xbox / PS3', 'PC / Xbox (retrocompatible)', 'ff', 28, 38, 58, 'Quedan trece días para el fin del mundo. Lightning despierta como salvadora de almas y debe rescatar a cuantos pueda antes del juicio final. Cierra la trilogía de XIII.', 'Hay un reloj real en partida; el Nuevo Juego+ conserva el progreso.', null, 'catalog'),
  ('ff-final-fantasy-xiv', 'Final Fantasy XIV', 2013, 'PC / PS5 / Xbox / Mac', 'Online (versión gratuita + expansiones)', 'ff', 380, 500, 900, 'El MMO de la saga, reconocido por su historia. Desde la caída de Dalamud en A Realm Reborn hasta las expansiones, cuenta una de las tramas más ambiciosas de toda la franquicia.', 'MMO con suscripción (la versión de prueba gratuita llega hasta nivel 70, Stormblood incluido). Las horas son solo la historia principal y expansiones; es aproximado.', null, 'catalog'),
  ('ff-final-fantasy-xv', 'Final Fantasy XV', 2016, 'PC / PS4 / Xbox', 'Royal Edition', 'ff', 32, 55, 100, 'Noctis, príncipe de Lucis, viaja en coche con sus tres amigos para casarse mientras su reino cae en manos del imperio de Niflheim. Road trip con final trágico.', 'La Royal Edition (o Windows Edition en PC) incluye los capítulos de Gladio, Prompto, Ignis y Ardyn, que completan la historia.', null, 'catalog'),
  ('ff-final-fantasy-xvi', 'Final Fantasy XVI', 2023, 'PC / PS5 / Xbox', 'Complete Edition (con DLC)', 'ff', 36, 52, 85, 'En Valisthea, los Dominantes encarnan a los Eikons y son armas de guerra. Clive Rosfield jura vengar a su hermano Joshua en una historia oscura de política, esclavitud y fuego.', 'Echoes of the Fallen y The Rising Tide añaden historia y contenido final. Combate de acción.', null, 'catalog'),
  ('zelda-the-legend-of-zelda', 'The Legend of Zelda', 1986, 'NES / Switch', 'Original de NES (Nintendo Switch Online)', 'zelda', 8, 10, 12, 'Ganon ha robado la Trifuerza del Poder y secuestrado a la princesa Zelda. Link debe reunir los ocho fragmentos de la Trifuerza de la Sabiduría repartidos por las mazmorras de Hyrule.', 'Juega con el mapa a mano: el original no te dice nada. La versión de Switch Online permite guardar en cualquier momento.', null, 'catalog'),
  ('zelda-zelda-ii-the-adventure-of-link', 'Zelda II: The Adventure of Link', 1987, 'NES / Switch', 'Original de NES (Nintendo Switch Online)', 'zelda', 10, 12, 15, 'Seis años después, Link descubre que Zelda está sumida en un sueño mágico. Para despertarla debe colocar seis cristales en seis palacios y alcanzar la Trifuerza del Valor.', 'La rareza de la saga: combate lateral, niveles de experiencia y pueblos. Muy difícil; los puntos de guardado de Switch ayudan.', null, 'catalog'),
  ('zelda-a-link-to-the-past', 'A Link to the Past', 1991, 'SNES / Switch', 'Original de SNES (Nintendo Switch Online)', 'zelda', 14, 17, 21, 'El mago Agahnim quiere romper el sello de los Siete Sabios. Link viaja entre el Mundo de la Luz y el Mundo Oscuro para recuperar la Espada Maestra y detener a Ganon.', 'La plantilla de casi todos los Zelda posteriores. Imprescindible.', null, 'catalog'),
  ('zelda-link-s-awakening', 'Link''s Awakening', 1993, 'Switch', 'Remake de Switch (2019)', 'zelda', 13, 17, 22, 'Tras un naufragio, Link despierta en la isla Koholint. Para salir de ella debe despertar al Pez del Viento con los ocho instrumentos de las sirenas, aunque eso tenga un precio.', 'El remake mantiene el diseño original con un estilo de juguete y mejoras de manejo.', null, 'catalog'),
  ('zelda-ocarina-of-time', 'Ocarina of Time', 1998, '3DS', 'Ocarina of Time 3D (3DS, 2011)', 'zelda', 28, 34, 42, 'Un niño sin hada del bosque Kokiri descubre su destino como Héroe del Tiempo. Viajando entre su infancia y su vida adulta intenta impedir que Ganondorf se haga con la Trifuerza.', 'La versión de 3DS mejora gráficos, inventario y la Mazmorra del Agua. Si no tienes 3DS, el original de N64 está en Switch Online.', null, 'catalog'),
  ('zelda-majora-s-mask', 'Majora''s Mask', 2000, '3DS', 'Majora''s Mask 3D (3DS, 2015)', 'zelda', 21, 29, 37, 'En Términa, la luna caerá en tres días. Link revive una y otra vez ese ciclo para ayudar a sus habitantes y detener a Skull Kid y la máscara que lo posee.', 'El más oscuro y melancólico de la saga. La versión 3D facilita el cuaderno de los Bombers y el guardado.', null, 'catalog'),
  ('zelda-oracle-of-seasons', 'Oracle of Seasons', 2001, 'GBC / Switch', 'Original de Game Boy Color (Nintendo Switch Online)', 'zelda', 14, 17, 21, 'La Triforce lleva a Link a Holodrum, donde el general Onox ha secuestrado a Din, el oráculo de las estaciones. Con la Vara de las Estaciones cambia el clima para avanzar.', 'Pareja de Oracle of Ages: termina uno y usa su contraseña para empezar el otro y desbloquear el final verdadero.', null, 'catalog'),
  ('zelda-oracle-of-ages', 'Oracle of Ages', 2001, 'GBC / Switch', 'Original de Game Boy Color (Nintendo Switch Online)', 'zelda', 17, 20, 24, 'En Labrynna, la hechicera Veran posee a Nayru, el oráculo del tiempo. Link viaja entre el presente y el pasado con el Arpa de las Eras.', 'El más centrado en puzles de la pareja Oracle.', null, 'catalog'),
  ('zelda-four-swords', 'Four Swords', 2002, 'GBA', 'Incluido en A Link to the Past & Four Swords (GBA)', 'zelda', 4, 5, 7, 'Link saca la Espada Cuádruple y se divide en cuatro para rescatar a Zelda del brujo del viento Vaati.', 'Pensado para jugar en multijugador local. Su historia se continúa en Four Swords Adventures.', null, 'catalog'),
  ('zelda-the-wind-waker', 'The Wind Waker', 2002, 'Wii U', 'The Wind Waker HD (Wii U, 2013)', 'zelda', 32, 40, 50, 'Siglos después de que Hyrule quedara bajo el mar, un chico de la isla Initia zarpa en busca de su hermana raptada y acaba descubriendo el legado del Héroe del Tiempo.', 'La versión HD acorta la búsqueda de la Trifuerza y añade la Vela Veloz.', null, 'catalog'),
  ('zelda-four-swords-adventures', 'Four Swords Adventures', 2004, 'GameCube', 'Original de GameCube', 'zelda', 13, 16, 20, 'Vaati ha escapado y un Link oscuro siembra el caos. Los cuatro Links recorren Hyrule por niveles para restaurar la Espada Cuádruple.', 'Se puede jugar solo, controlando a los cuatro Links en formaciones.', null, 'catalog'),
  ('zelda-the-minish-cap', 'The Minish Cap', 2004, 'GBA / Switch', 'Original de GBA (Nintendo Switch Online)', 'zelda', 13, 16, 20, 'Vaati convierte a Zelda en piedra. Con Ezero, un gorro parlante, Link encoge hasta el tamaño de los minish para encontrar la forma de salvarla. El origen de Vaati y de la Espada Cuádruple.', 'Corto, precioso y con mucha imaginación en las mazmorras.', null, 'catalog'),
  ('zelda-twilight-princess', 'Twilight Princess', 2006, 'Wii U', 'Twilight Princess HD (Wii U, 2016)', 'zelda', 42, 51, 62, 'El Crepúsculo cubre Hyrule. Link, convertido en lobo, y Midna, princesa del Reino del Crepúsculo, se alían para detener a Zant y a quien lo controla.', 'La versión HD reduce la búsqueda de Lágrimas de Luz y mejora el manejo.', null, 'catalog'),
  ('zelda-phantom-hourglass', 'Phantom Hourglass', 2007, 'DS', 'Original de DS', 'zelda', 21, 26, 31, 'Secuela directa de The Wind Waker: Tetra desaparece en un barco fantasma y Link navega por el Mar del Rey Oceánico con el capitán Linebeck.', 'Se juega entero con el lápiz táctil. El Templo del Rey del Mar se repite varias veces.', null, 'catalog'),
  ('zelda-spirit-tracks', 'Spirit Tracks', 2009, 'DS', 'Original de DS', 'zelda', 25, 30, 37, 'Un siglo después, Link es aprendiz de maquinista. Las vías espirituales desaparecen y el espíritu de Zelda lo acompaña, poseyendo armaduras, para restaurar la Torre de los Dioses.', 'Zelda como compañera jugable. El tren sustituye al barco.', null, 'catalog'),
  ('zelda-skyward-sword', 'Skyward Sword', 2011, 'Switch', 'Skyward Sword HD (Switch, 2021)', 'zelda', 35, 43, 54, 'El origen de la saga: Link y Zelda viven en Altárea, sobre las nubes. Cuando Zelda cae a la superficie, Link desciende para encontrarla y forjar la Espada Maestra.', 'La versión HD permite jugar sin control por movimiento y reduce las interrupciones de Fi.', null, 'catalog'),
  ('zelda-a-link-between-worlds', 'A Link Between Worlds', 2013, '3DS', 'Original de 3DS', 'zelda', 16, 21, 26, 'Yuga convierte a los Siete Sabios en cuadros. Link puede fundirse con las paredes como un dibujo y viaja entre Hyrule y Lorule.', 'Secuela espiritual de A Link to the Past; puedes alquilar los objetos y hacer las mazmorras en el orden que quieras.', null, 'catalog'),
  ('zelda-tri-force-heroes', 'Tri Force Heroes', 2015, '3DS', 'Original de 3DS', 'zelda', 15, 21, 34, 'En el reino de Vestidia, una bruja ha maldecido a la princesa Estilia. Tres héroes forman tótems y comparten vida para recorrer las Tierras Malditas.', 'Hecho para tres jugadores. En solitario controlas a muñecos de uno en uno.', null, 'catalog'),
  ('zelda-breath-of-the-wild', 'Breath of the Wild', 2017, 'Switch / Switch 2', 'Nintendo Switch 2 Edition (2025)', 'zelda', 50, 100, 190, 'Link despierta tras cien años de sueño en un Hyrule en ruinas. Sin recuerdos, explora un mundo abierto para recuperar a las cuatro Bestias Divinas y enfrentarse al Cataclismo.', 'La edición de Switch 2 mejora resolución y fluidez y añade la app Zelda Notes. Empieza con los DLC ya instalados si los tienes.', null, 'catalog'),
  ('zelda-tears-of-the-kingdom', 'Tears of the Kingdom', 2023, 'Switch / Switch 2', 'Nintendo Switch 2 Edition (2025)', 'zelda', 60, 120, 220, 'Bajo el castillo de Hyrule despierta Ganondorf. Hyrule se llena de islas celestes y abismos, y Link usa el poder de Rauru para construir y explorar en tres capas de mundo.', 'Juégalo después de Breath of the Wild: es su secuela directa.', null, 'catalog'),
  ('zelda-echoes-of-wisdom', 'Echoes of Wisdom', 2024, 'Switch', 'Original de Switch', 'zelda', 20, 28, 36, 'Unas grietas se tragan a la gente de Hyrule, incluido Link. Zelda toma la iniciativa con la vara de Tri y crea copias de objetos y monstruos para resolver cada situación.', 'La primera vez que Zelda protagoniza un juego principal de la saga.', null, 'catalog'),
  ('kirby-kirby-s-dream-land', 'Kirby''s Dream Land', 1992, 'GB / Switch', 'Original de Game Boy (Nintendo Switch Online)', 'kirby', 1, 2, 2, 'El rey Dedede ha robado toda la comida de Dream Land. Kirby lo persigue hasta el Castillo Lololo en su primera aventura, todavía sin poderes de copia.', 'Se termina en una tarde. Cuando lo acabes, prueba el modo extra.', null, 'catalog'),
  ('kirby-kirby-s-adventure', 'Kirby''s Adventure', 1993, 'GBA / Switch', 'Kirby: Nightmare in Dream Land (GBA, 2002)', 'kirby', 5, 7, 10, 'La Fuente de los Sueños se ha secado y nadie en Dream Land puede soñar. Kirby debe recuperar las piezas de la Vara Estelar que Dedede ha repartido entre sus secuaces.', 'El remake de GBA sustituye al original de NES y añade modo con Meta Knight y minijuegos.', null, 'catalog'),
  ('kirby-kirby-s-dream-land-2', 'Kirby''s Dream Land 2', 1995, 'GB / Switch', 'Original de Game Boy (Nintendo Switch Online)', 'kirby', 3, 5, 7, 'La Oscura Materia ha robado el Puente Arcoíris y controla a Dedede. Kirby recibe la ayuda de Rick, Kine y Coo, tres amigos animales que cambian sus poderes.', 'Busca las Estrellas Arcoíris para ver el final verdadero.', null, 'catalog'),
  ('kirby-kirby-super-star', 'Kirby Super Star', 1996, 'DS', 'Kirby Super Star Ultra (DS, 2008)', 'kirby', 8, 12, 16, 'Una colección de aventuras: un viaje para recuperar la comida, la Gran Cueva, la Revancha de Meta Knight, el Milky Way Wishes con Marx y más.', 'La versión de DS es la definitiva: añade cuatro modos nuevos sobre el original de SNES.', null, 'catalog'),
  ('kirby-kirby-s-dream-land-3', 'Kirby''s Dream Land 3', 1997, 'SNES / Switch', 'Original de SNES (Nintendo Switch Online)', 'kirby', 6, 9, 12, 'Una nube de Materia Oscura cubre Pop Star. Kirby y Gooey, con sus amigos animales, recorren el planeta ayudando a sus habitantes.', 'Ayudar a cada personaje da el Corazón que desbloquea el final verdadero.', null, 'catalog'),
  ('kirby-kirby-64-the-crystal-shards', 'Kirby 64: The Crystal Shards', 2000, 'N64 / Switch', 'Original de N64 (Nintendo Switch Online + Paquete de expansión)', 'kirby', 5, 7, 9, 'El gran cristal del hada Ribbon estalla en mil pedazos al ser atacado por la Materia Oscura. Kirby recorre la galaxia para recuperarlos.', 'Combina dos habilidades para crear poderes nuevos.', null, 'catalog'),
  ('kirby-kirby-the-amazing-mirror', 'Kirby & The Amazing Mirror', 2004, 'GBA / Switch', 'Original de GBA (Nintendo Switch Online)', 'kirby', 7, 10, 14, 'El Espejo Dimensional ha sido corrompido. Kirby, dividido en cuatro, explora un laberinto interconectado de mundos.', 'Es un metroidvania: el mundo es un mapa abierto en vez de niveles.', null, 'catalog'),
  ('kirby-kirby-squeak-squad', 'Kirby: Squeak Squad', 2006, 'DS', 'Original de DS', 'kirby', 5, 8, 12, 'Alguien ha robado la tarta de fresa de Kirby. Persiguiendo a la banda de ratones Squeaks, descubre un cofre que guarda algo mucho más peligroso.', 'Puedes guardar y combinar habilidades en el estómago de Kirby (la pantalla táctil).', null, 'catalog'),
  ('kirby-kirby-s-return-to-dream-land', 'Kirby''s Return to Dream Land', 2011, 'Switch', 'Kirby''s Return to Dream Land Deluxe (Switch, 2023)', 'kirby', 8, 13, 19, 'La nave Lor Starcutter de Magolor se estrella en Pop Star. Kirby y sus amigos recuperan sus piezas para ayudarle a volver a casa.', 'El Deluxe añade el epílogo Magolor Epilogue y una feria de minijuegos.', null, 'catalog'),
  ('kirby-kirby-triple-deluxe', 'Kirby: Triple Deluxe', 2014, '3DS', 'Original de 3DS', 'kirby', 8, 12, 17, 'Un tallo gigante, el Planta Sueño, se lleva el castillo de Dedede al cielo. Kirby sube hasta Floralia para rescatarlo de Taranza.', 'Juega con la profundidad: los niveles saltan entre el primer plano y el fondo.', null, 'catalog'),
  ('kirby-kirby-planet-robobot', 'Kirby: Planet Robobot', 2016, '3DS', 'Original de 3DS', 'kirby', 8, 12, 18, 'La corporación Haltmann mecaniza Pop Star. Kirby se pone a los mandos de un robot para detener la invasión.', 'Para muchos fans, el mejor Kirby en 2D.', null, 'catalog'),
  ('kirby-kirby-star-allies', 'Kirby Star Allies', 2018, 'Switch', 'Original de Switch', 'kirby', 6, 10, 15, 'Unos corazones oscuros caen por la galaxia y convierten a los habitantes de Pop Star en villanos. Kirby puede hacerse amigo de sus enemigos lanzándoles corazones.', 'Las actualizaciones gratuitas añaden muchos aliados de la saga.', null, 'catalog'),
  ('kirby-kirby-and-the-forgotten-land', 'Kirby and the Forgotten Land', 2022, 'Switch / Switch 2', 'Nintendo Switch 2 Edition + Star-Crossed World (2025)', 'kirby', 14, 20, 30, 'Un vórtice arrastra a Kirby a un mundo abandonado donde la naturaleza ha reconquistado una civilización humana. Allí la Bestia secuestra a los Waddle Dee.', 'La edición de Switch 2 añade la expansión Star-Crossed World. El primer Kirby en 3D completo.', null, 'catalog'),
  ('mario-super-mario-bros', 'Super Mario Bros.', 1985, 'NES / Switch', 'Original de NES (Nintendo Switch Online)', 'mario', 2, 4, 7, 'Bowser ha secuestrado a la princesa Peach y ha convertido a los habitantes del Reino Champiñón en bloques. Mario cruza ocho mundos para rescatarla.', 'Busca las tuberías de atajo... o no, y disfruta los 32 niveles.', null, 'catalog'),
  ('mario-super-mario-bros-the-lost-levels', 'Super Mario Bros.: The Lost Levels', 1986, 'SNES / Switch', 'Incluido en Super Mario All-Stars (Switch Online)', 'mario', 4, 6, 9, 'La verdadera secuela japonesa de Super Mario Bros.: los mismos personajes, pero con niveles mucho más crueles, viento y champiñones venenosos.', 'Solo para valientes. La versión de All-Stars guarda la partida.', null, 'catalog'),
  ('mario-super-mario-bros-2', 'Super Mario Bros. 2', 1988, 'NES / Switch', 'Original de NES (Nintendo Switch Online)', 'mario', 3, 4, 6, 'Mario, Luigi, Peach y Toad entran en un sueño, Subcon, y deben derrotar al rey Wart arrancando verduras y lanzándoselas a los enemigos.', 'Cada personaje juega distinto: Peach flota y Luigi salta más.', null, 'catalog'),
  ('mario-super-mario-bros-3', 'Super Mario Bros. 3', 1988, 'NES / Switch', 'Original de NES (Nintendo Switch Online)', 'mario', 6, 9, 12, 'Los Koopalings han robado las varitas de los reyes de siete reinos. Mario recorre un mapa con niveles, minijuegos y trajes como el de mapache o el de rana.', 'Uno de los mejores plataformas de la historia.', null, 'catalog'),
  ('mario-super-mario-land', 'Super Mario Land', 1989, 'GB / Switch', 'Original de Game Boy (Nintendo Switch Online)', 'mario', 1, 2, 2, 'El alienígena Tatanga ha secuestrado a la princesa Daisy en Sarasaland. Mario cruza cuatro reinos, con fases en submarino y avión.', 'Muy corto y algo extraño, pero con encanto.', null, 'catalog'),
  ('mario-super-mario-world', 'Super Mario World', 1990, 'SNES / Switch', 'Original de SNES (Nintendo Switch Online)', 'mario', 7, 12, 16, 'De vacaciones en Dinosaur Land, Peach desaparece. Mario y su nuevo amigo Yoshi recorren la isla para liberar a los huevos de Yoshi y a la princesa.', 'Busca las salidas secretas: llevan al Mundo Especial.', null, 'catalog'),
  ('mario-super-mario-land-2-6-golden-coins', 'Super Mario Land 2: 6 Golden Coins', 1992, 'GB / Switch', 'Original de Game Boy (Nintendo Switch Online)', 'mario', 3, 4, 5, 'Mientras Mario estaba fuera, Wario ha tomado su castillo. Mario necesita las seis monedas doradas para abrir la puerta.', 'El debut de Wario.', null, 'catalog'),
  ('mario-super-mario-64', 'Super Mario 64', 1996, 'N64 / Switch', 'Original de N64 (Nintendo Switch Online + Paquete de expansión)', 'mario', 12, 18, 25, 'Peach invita a Mario a su castillo, pero Bowser lo ha tomado. Mario salta dentro de los cuadros para conseguir las Superestrellas y abrir las puertas.', 'El primer Mario en 3D y la base de todos los que vinieron después.', null, 'catalog'),
  ('mario-super-mario-sunshine', 'Super Mario Sunshine', 2002, 'GameCube', 'Incluido en Super Mario 3D All-Stars / original de GameCube', 'mario', 17, 25, 35, 'En vacaciones en Isla Delfino, un impostor llena la isla de pintura y culpan a Mario. Con el aparato de agua A.C.U.A.C. debe limpiarla para limpiar su nombre.', 'Las monedas azules del 100 % son una prueba de paciencia.', null, 'catalog'),
  ('mario-new-super-mario-bros', 'New Super Mario Bros.', 2006, 'DS', 'Original de DS', 'mario', 7, 10, 15, 'Bowser Jr. secuestra a Peach. Mario vuelve al 2D con champiñones gigantes y diminutos y el caparazón azul.', 'El regreso del Mario 2D clásico tras más de diez años.', null, 'catalog'),
  ('mario-super-mario-galaxy', 'Super Mario Galaxy', 2007, 'Switch', 'Super Mario Galaxy + Super Mario Galaxy 2 (Switch, 2025)', 'mario', 15, 21, 35, 'Bowser se lleva el castillo de Peach al espacio. Mario conoce a Estela y su Observatorio, y viaja entre planetas con gravedad propia para recuperar las Superestrellas.', 'Uno de los mejores juegos de la historia. Juega con Luigi tras terminarlo.', null, 'catalog'),
  ('mario-new-super-mario-bros-wii', 'New Super Mario Bros. Wii', 2009, 'Wii', 'Original de Wii', 'mario', 7, 11, 17, 'Durante el cumpleaños de Peach, los Koopalings salen de una tarta y la secuestran. Mario, Luigi y dos Toads la persiguen por ocho mundos.', 'Brilla en multijugador local a cuatro.', null, 'catalog'),
  ('mario-super-mario-galaxy-2', 'Super Mario Galaxy 2', 2010, 'Switch', 'Super Mario Galaxy + Super Mario Galaxy 2 (Switch, 2025)', 'mario', 15, 23, 40, 'Bowser, gigante, vuelve a llevarse a Peach al centro del universo. Mario viaja en la Nave Mario con Yoshi y nuevas habilidades.', 'Más difícil y variado que el primero. El 100 % incluye las estrellas verdes.', null, 'catalog'),
  ('mario-super-mario-3d-land', 'Super Mario 3D Land', 2011, '3DS', 'Original de 3DS', 'mario', 8, 14, 20, 'Una tormenta deja sin hojas al Árbol Súper Hoja y Bowser secuestra a Peach. Mario recupera el traje de mapache en niveles cortos en 3D.', 'Los mundos especiales tras el final doblan el juego.', null, 'catalog'),
  ('mario-new-super-mario-bros-2', 'New Super Mario Bros. 2', 2012, '3DS', 'Original de 3DS', 'mario', 5, 8, 14, 'Los Koopalings secuestran a Peach. Mario se lanza a reunir un millón de monedas por el camino.', 'El más ligero de la subserie New.', null, 'catalog'),
  ('mario-new-super-mario-bros-u', 'New Super Mario Bros. U', 2012, 'Switch', 'New Super Mario Bros. U Deluxe (Switch, 2019)', 'mario', 10, 16, 25, 'Bowser expulsa a Mario del castillo de Peach y lo toma. Mario cruza un mapa continuo para volver, con el traje de ardilla voladora.', 'El Deluxe incluye New Super Luigi U, más corto y más difícil.', null, 'catalog'),
  ('mario-super-mario-3d-world', 'Super Mario 3D World', 2013, 'Switch', 'Super Mario 3D World + Bowser''s Fury (Switch, 2021)', 'mario', 16, 24, 31, 'Bowser embotella a las hadas del Reino de las Hadas. Mario, Luigi, Peach y Toad las rescatan con el traje de gato. Bowser’s Fury añade una isla abierta con Bowser Jr.', 'Perfecto para jugar acompañado.', null, 'catalog'),
  ('mario-super-mario-odyssey', 'Super Mario Odyssey', 2017, 'Switch', 'Original de Switch', 'mario', 13, 40, 65, 'Bowser quiere casarse con Peach a la fuerza. Mario y Cappy, un sombrero con vida, viajan por reinos en la nave Odyssey capturando enemigos y objetos.', 'Hay 999 lunas; para terminar la historia bastan unas cien.', null, 'catalog'),
  ('mario-super-mario-bros-wonder', 'Super Mario Bros. Wonder', 2023, 'Switch', 'Original de Switch', 'mario', 12, 18, 26, 'En el Reino Flor, Bowser se fusiona con un castillo. Las Flores Maravilla transforman cada nivel de formas sorprendentes.', 'El Mario 2D más creativo en décadas.', null, 'catalog'),
  ('xeno-xenoblade-chronicles', 'Xenoblade Chronicles', 2010, 'Switch / Switch 2', 'Definitive Edition', 'xeno', 68, 100, 180, 'Sobre los cuerpos de dos titanes muertos viven todos los pueblos del mundo. Cuando los Mechon arrasan su colonia, Shulk empuña la Monado, una espada capaz de ver el futuro, y emprende una venganza que acaba cuestionando el orden del universo.', 'Incluye Future Connected, el epílogo canónico (~12 h). La horquilla de horas lo contempla.', null, 'catalog'),
  ('xeno-xenoblade-chronicles-x', 'Xenoblade Chronicles X', 2015, 'Switch / Switch 2', 'Definitive Edition (2025)', 'xeno', 52, 100, 170, 'La Tierra ha sido destruida en una guerra alienígena y la nave arca de Nueva Los Ángeles se estrella en el planeta Mira. Como miembro de BLADE, exploras un continente gigantesco en Skells mientras buscas el núcleo que mantiene viva a la humanidad.', 'La Definitive Edition añade un capítulo final nuevo que conecta con el resto de la saga.', null, 'catalog'),
  ('xeno-xenoblade-chronicles-2', 'Xenoblade Chronicles 2', 2017, 'Switch / Switch 2', 'Edición estándar', 'xeno', 72, 110, 180, 'Un mar de nubes cubre Alrest y los titanes que sostienen a sus naciones se mueren. Rex, un chatarrero, se une a Pyra, la legendaria Égida, para llegar al Elysium, el paraíso perdido en la cima del Árbol del Mundo.', 'Para mejor ritmo, activa la dificultad Fácil o Personalizada si el gacha de Blades se hace pesado.', null, 'catalog'),
  ('xeno-torna-the-golden-country', 'Torna: The Golden Country', 2018, 'Switch', 'Expansión independiente', 'xeno', 20, 28, 42, 'Precuela de Xenoblade 2 ambientada 500 años antes. Cuenta la guerra contra Malos y el destino de Lora, Jin y Addam. Da contexto clave a varios personajes de XC2.', 'Se vende por separado o en el Expansion Pass. Jugar después de XC2.', null, 'catalog'),
  ('xeno-xenoblade-chronicles-3', 'Xenoblade Chronicles 3', 2022, 'Switch / Switch 2', 'Edición estándar', 'xeno', 65, 110, 170, 'En Aionios, Keves y Agnus libran una guerra eterna con soldados que solo viven diez años. Noah y Mio rompen la cadena y huyen juntos hacia el lugar donde dicen que la vida puede ser libre.', 'Es el cierre del arco de XC1 y XC2. Jugarlo después de ambos multiplica su impacto.', null, 'catalog'),
  ('xeno-xenoblade-3-future-redeemed', 'Xenoblade 3: Future Redeemed', 2023, 'Switch / Switch 2', 'Expansión (Expansion Pass)', 'xeno', 20, 26, 38, 'Precuela de XC3 protagonizada por Matthew y A, que cierra todo el universo de Xenoblade y responde a preguntas pendientes desde el primer juego.', 'Capítulo final de la saga. Jugar en último lugar.', null, 'catalog'),
  ('metroid-metroid-zero-mission', 'Metroid: Zero Mission', 2004, 'GBA (Switch Online)', 'Remake del Metroid de NES', 'metroid', 4, 5, 7, 'Samus Aran se infiltra en Zebes para destruir a los piratas espaciales y a Mother Brain. El remake añade un epílogo jugable tras perder su traje.', 'Sustituye al Metroid original de 1986. Disponible en Nintendo Switch Online + Paquete de expansión.', null, 'catalog'),
  ('metroid-metroid-samus-returns', 'Metroid: Samus Returns', 2017, '3DS', 'Remake de Metroid II', 'metroid', 10, 12, 16, 'La Federación encarga a Samus exterminar a los Metroids en su planeta natal, SR388. Al final de la cacería encuentra algo que cambiará su destino.', 'Sustituye a Metroid II: Return of Samus (Game Boy, 1991).', null, 'catalog'),
  ('metroid-super-metroid', 'Super Metroid', 1994, 'SNES (Switch Online)', 'Original SNES', 'metroid', 6, 7, 9, 'Una cría de Metroid es robada por Ridley y Samus vuelve a Zebes para recuperarla. La obra maestra que fundó el género metroidvania.', 'Sigue siendo la mejor versión. En Nintendo Switch Online.', null, 'catalog'),
  ('metroid-metroid-fusion', 'Metroid Fusion', 2002, 'GBA (Switch Online)', 'Original GBA', 'metroid', 6, 7, 8, 'Samus es infectada por el parásito X y sobrevive gracias a una vacuna de Metroid. A bordo de una estación biológica, la persigue una copia exacta de sí misma: el SA-X.', 'Disponible en Nintendo Switch Online + Paquete de expansión.', null, 'catalog'),
  ('metroid-metroid-prime-remastered', 'Metroid Prime Remastered', 2002, 'Switch / Switch 2', 'Remastered (2023)', 'metroid', 13, 16, 20, 'Samus responde a una señal de socorro y llega a Tallon IV, un planeta contaminado por la sustancia Phazon. La saga en primera persona y exploración pura.', 'Remasterización con gráficos nuevos y controles modernos. Sustituye al de GameCube.', null, 'catalog'),
  ('metroid-metroid-prime-2-echoes', 'Metroid Prime 2: Echoes', 2004, 'Wii / Wii U', 'Metroid Prime Trilogy (Wii)', 'metroid', 17, 20, 25, 'En Aether, Samus descubre un mundo partido en dos dimensiones: una luminosa y otra oscura y tóxica. Los Ing y la misteriosa Dark Samus acechan.', 'Trilogy (Wii) tiene los mejores controles. Sin remaster en Switch por ahora.', null, 'catalog'),
  ('metroid-metroid-prime-3-corruption', 'Metroid Prime 3: Corruption', 2007, 'Wii / Wii U', 'Metroid Prime Trilogy (Wii)', 'metroid', 15, 17, 21, 'Samus queda corrompida por el Phazon y lucha contra la propagación de Dark Samus por toda la galaxia. Cierre de la trilogía Prime.', 'Trilogy (Wii).', null, 'catalog'),
  ('metroid-metroid-other-m', 'Metroid: Other M', 2010, 'Wii', 'Original Wii', 'metroid', 10, 12, 15, 'Situado justo después de Super Metroid, Samus responde a una señal de una nave abandonada y se reencuentra con su antiguo comandante. Mucho énfasis narrativo en su pasado.', 'Canónico, aunque es el más polémico de la saga por su enfoque en Samus.', null, 'catalog'),
  ('metroid-metroid-dread', 'Metroid Dread', 2021, 'Switch / Switch 2', 'Original Switch', 'metroid', 9, 11, 14, 'El parásito X sigue vivo en el planeta ZDR. Samus va a investigar y se enfrenta a los E.M.M.I., robots que la persiguen sin descanso. Cierra el arco narrativo iniciado en el primer juego.', 'Jugar después de Fusion.', null, 'catalog'),
  ('metroid-metroid-prime-4-beyond', 'Metroid Prime 4: Beyond', 2025, 'Switch / Switch 2', 'Switch 2 Edition', 'metroid', 15, 19, 24, 'Samus es transportada a Viewros, un planeta desconocido, y descubre poderes psíquicos. Entrega número cuatro de la línea Prime tras años de desarrollo.', 'Las horas son una estimación inicial; pueden variar con más datos de jugadores.', null, 'catalog')
insert into public.lists (id, owner_id, name, description, visibility, color, color2, icon, official) values
  ('official-persona', null, 'Persona', 'Atlus · JRPG social y mazmorras. Los cinco Persona principales y su secuela canónica, cada uno en su versión definitiva.', 'public', '#ff2a4d', '#2ef2ff', 'flame', true),
  ('official-fe', null, 'Fire Emblem', 'Intelligent Systems · estrategia táctica. Todos los Fire Emblem principales. Cuando existe remake se juega el remake; los que solo salieron en Japón, con su traducción de fans.', 'public', '#f5c96a', '#ff5a7a', 'shield', true),
  ('official-ff', null, 'Final Fantasy', 'Square Enix · numerados principales. Los Final Fantasy numerados y sus secuelas directas, cada uno en la versión más cuidada que puedes jugar hoy.', 'public', '#5aa9ff', '#f5c96a', 'diamond', true),
  ('official-zelda', null, 'The Legend of Zelda', 'Nintendo · aventura y mazmorras. Todos los Zelda canónicos de la cronología oficial, de Hyrule en 8 bits a Tears of the Kingdom y Echoes of Wisdom.', 'public', '#2f9e58', '#e8c547', 'triangle', true),
  ('official-kirby', null, 'Kirby', 'HAL Laboratory · plataformas y copia. La serie principal de Kirby, de Dream Land en Game Boy a la aventura en 3D de Forgotten Land.', 'public', '#ff8fc8', '#7fd6ff', 'star', true),
  ('official-mario', null, 'Super Mario', 'Nintendo · plataformas. Los plataformas principales de Mario en 2D y 3D, desde Super Mario Bros. hasta Wonder.', 'public', '#e53935', '#ffd23f', 'flash', true),
  ('official-xeno', null, 'Xenoblade', 'Monolith Soft · JRPG de mundo abierto. Los cuatro Xenoblade y sus expansiones de historia, que son capítulos canónicos imprescindibles.', 'public', '#37e6c2', '#7aa8ff', 'planet', true),
  ('official-metroid', null, 'Metroid', 'Nintendo · exploración y ciencia ficción. Toda la línea canónica de Samus Aran, sustituyendo los originales por sus remakes cuando existen.', 'public', '#ff8a2a', '#7ef2a4', 'rocket', true)
