-- Generado por scripts/generate-seed.js. No lo edites a mano.
begin;

on conflict (id) do update set title = excluded.title, year = excluded.year, platforms = excluded.platforms, version = excluded.version, main = excluded.main, extra = excluded.extra, "full" = excluded."full", synopsis = excluded.synopsis, note = excluded.note;

on conflict (id) do update set name = excluded.name, description = excluded.description, color = excluded.color, color2 = excluded.color2, icon = excluded.icon;

delete from public.list_items where list_id like 'official-%';

commit;
